export const levels=[{id:'125',label:'125 hours',funding:750,description:'ECR development'},{id:'250',label:'250 hours',funding:1000,description:'Level 1'},{id:'350',label:'350 hours',funding:1500,description:'Level 2'},{id:'425',label:'425 hours',funding:2500,description:'Level 3'}];
export const configs={
 submissions:{title:'Current submissions',target:'submissionsRows',fields:[['details','Submission details','textarea'],['journal','Journal / publisher','journal'],['ajg','AJG 2024','rank'],['sjr','SJR score','rank'],['status','Status','text']]},
 workInProgress:{title:'Work in progress',target:'workInProgressRows',fields:[['project','Research project','textarea'],['plans','Publication plans','textarea'],['journal','Target journal','journal'],['ajg','AJG 2024','rank'],['sjr','SJR score','rank'],['ethics','Ethics application','text'],['targetDate','Target date','text']]},
 refOutputs:{title:'REF outputs',target:'refOutputsRows',fields:[['reference','Reference','textarea'],['refRating','Self-assessed REF rating','select',['','2*','3*','4*']],['openAccess','Open access / VRE','text'],['ajg','AJG','text'],['sjr','SJR','text']]},
 income:{title:'Income and bids',target:'incomeRows',fields:[['vreUrl','VRE URL','text'],['name','Project / bid name','text'],['year','Year','text'],['value','Total value (£)','text'],['role','Role','select',['','PI','Co-I','Other']],['outcome','Outcome','text'],['ethics','Ethics status','text']]},
 conferences:{title:'Conferences',target:'conferencesRows',fields:[['project','Research project','text'],['paper','Paper / event','text'],['conference','Conference','text'],['publication','Publication status','text']]},
 culture:{title:'Culture and esteem',target:'cultureRows',fields:[['category','Category','select',['','Professional / learned society memberships and roles','Conference or professional event organisation','Funding body activities','Editorial work','Awards, honours, and prizes','Keynote presentations','Other']],['activity','Activity','textarea'],['vreEntry','VRE entry','text']]}
};
export function newApplication(){const now=new Date().toISOString();return {schema:'rsa-applicant',schemaVersion:1,id:crypto.randomUUID(),createdAt:now,updatedAt:now,status:'Draft',finalizedAt:null,applicant:{name:'',email:'',school:'',fte:'',centre:'',academicYear:'2026/27',orcid:'',ecrYear:''},request:{mainAllowance:'',piBid:0,ciBid:0,rrAward:false},answers:{mitigation:'',phdSupervision:'',futurePlans:'',impact:''},publications:[],...Object.fromEntries(Object.keys(configs).map(k=>[k,[]])),declaration:false};}
export function totals(app){const main=levels.find(l=>l.id===app.request.mainAllowance);const raw=Number(app.request.piBid||0)+Number(app.request.ciBid||0);return {baseHours:Number(main?.id||0),bidHours:Math.min(raw,120),rawBidHours:raw,rrHours:app.request.rrAward?30:0,hours:Number(main?.id||0)+Math.min(raw,120)+(app.request.rrAward?30:0),funding:main?.funding??0};}
const str=(v,max=60000)=>typeof v==='string'?v.slice(0,max):typeof v==='number'?String(v):'';
export function readApplication(raw){
 if(!raw||raw.schema!=='rsa-applicant'||raw.schemaVersion!==1||!raw.applicant||!raw.request)throw new Error('Choose an application JSON file saved by this applicant app.');
 const out=newApplication();
 for(const key of ['id','createdAt','updatedAt','finalizedAt'])if(raw[key])out[key]=str(raw[key],200);
 for(const key of Object.keys(out.applicant))out.applicant[key]=str(raw.applicant[key],1000);
 for(const key of Object.keys(out.answers))out.answers[key]=str(raw.answers?.[key]);
 out.request.mainAllowance=levels.some(l=>l.id===raw.request.mainAllowance)?raw.request.mainAllowance:'';
 out.request.piBid=[0,30,75,120].includes(Number(raw.request.piBid))?Number(raw.request.piBid):0;
 out.request.ciBid=[0,30,75].includes(Number(raw.request.ciBid))?Number(raw.request.ciBid):0;out.request.rrAward=raw.request.rrAward===true;
 out.status=raw.status==='Ready for review'?'Ready for review':'Draft';out.declaration=raw.declaration===true;
 for(const [key,config] of Object.entries(configs))out[key]=(Array.isArray(raw[key])?raw[key]:[]).filter(row=>row&&typeof row==='object').slice(0,2000).map(row=>({id:str(row.id,200)||crypto.randomUUID(),...Object.fromEntries(config.fields.map(([field])=>[field,str(row[field])])),...(row.publicationId?{publicationId:str(row.publicationId,200)}:{})}));
 const ids=new Set();out.publications=(Array.isArray(raw.publications)?raw.publications:[]).filter(p=>p&&typeof p==='object').slice(0,5000).map(p=>{let id=str(p.id,200)||crypto.randomUUID();if(ids.has(id))id=crypto.randomUUID();ids.add(id);return {id,type:str(p.type,100),apa:str(p.apa),title:str(p.title),journal:str(p.journal,2000),year:str(p.year,20),doi:str(p.doi,2000),vreUrl:str(p.vreUrl,4000),ajg:str(p.ajg,50),sjr:str(p.sjr,50),sjrQuartile:str(p.sjrQuartile,50),rankingMatch:str(p.rankingMatch,100),source:str(p.source,100),issues:Array.isArray(p.issues)?p.issues.map(x=>str(x,500)).slice(0,30):[],issns:Array.isArray(p.issns)?p.issns.map(x=>str(x,100)).slice(0,10):[]};});
 return out;
}
export function validation(app){const errors=[];if(!app.applicant.name.trim())errors.push('Enter your name (Step 1).');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(app.applicant.email))errors.push('Enter a valid university email address (Step 1).');if(!app.applicant.school)errors.push('Choose your School (Step 1).');if(!(Number(app.applicant.fte)>0&&Number(app.applicant.fte)<=1))errors.push('Enter fractional status between 0.01 and 1.0 FTE (Step 1).');if(!app.applicant.academicYear.trim())errors.push('Enter the academic year (Step 1).');if(!app.request.mainAllowance)errors.push('Choose a main allowance (Step 1).');if(app.request.mainAllowance==='125'&&!app.applicant.ecrYear)errors.push('Choose your ECR development year (Step 1).');if(app.publications.some(p=>!p.apa.trim()))errors.push('Complete or remove blank publication references (Step 2).');if(!app.declaration)errors.push('Confirm the declaration on this page.');return errors;}
export function fileStem(app){return 'RSA-'+app.applicant.academicYear.replace(/[^a-z0-9]/gi,'-')+'-'+(app.applicant.name||'draft').replace(/[^a-z0-9_-]/gi,'-').replace(/-+/g,'-')+'-'+app.id.slice(0,8);}
export function csvRow(values){return values.map(v=>{let text=String(v??'');if(/^[\s\uFEFF]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}).join(',');}
export function applicationCsv(app){const total=totals(app);const row={application_id:app.id,status:app.status,created_at:app.createdAt,updated_at:app.updatedAt,finalized_at:app.finalizedAt??'',...Object.fromEntries(Object.entries(app.applicant).map(([k,v])=>['applicant_'+k,v])),...Object.fromEntries(Object.entries(app.request).map(([k,v])=>['request_'+k,v])),total_hours:total.hours,research_allowance_gbp:total.funding,publication_count:app.publications.length,...Object.fromEntries(Object.entries(app.answers).map(([k,v])=>['answer_'+k,v])),publications:app.publications.map((p,i)=>`${i+1}. ${p.apa}\nType: ${p.type}; Year: ${p.year}; Journal: ${p.journal}; DOI: ${p.doi}; AJG 2024: ${p.ajg}; SJR: ${p.sjr}; Quartile: ${p.sjrQuartile}; VRE: ${p.vreUrl}; Match: ${p.rankingMatch}; Source: ${p.source}${p.issues.length?'\nCheck: '+p.issues.join('; '):''}`).join('\n\n'),...Object.fromEntries(Object.entries(configs).map(([key,config])=>[key,app[key].map((r,i)=>`${i+1}. `+config.fields.map(([field,label])=>`${label}: ${r[field]??''}`).join(' | ')).join('\n')])),declaration:app.declaration};return '\uFEFF'+csvRow(Object.keys(row))+'\r\n'+csvRow(Object.values(row))+'\r\n';}
export function normalizeTitle(x){return String(x??'').toLowerCase().replace(/&amp;/g,'&').replace(/[^a-z0-9]/g,'');}
export function rankingIndex(data){const cTitle=new Map(),sTitle=new Map(),cIssn=new Map(),sIssn=new Map();for(const r of data.cabs??[]){cTitle.set(normalizeTitle(r.title),r);for(const id of r.issns??[])cIssn.set(normalizeTitle(id),r);}for(const r of data.sjr??[]){sTitle.set(normalizeTitle(r.title),r);for(const id of r.issns??[])sIssn.set(normalizeTitle(id),r);}return (title,issns=[])=>{const ct=issns.map(x=>cIssn.get(normalizeTitle(x))).find(Boolean),st=issns.map(x=>sIssn.get(normalizeTitle(x))).find(Boolean);const c=ct??cTitle.get(normalizeTitle(title)),s=st??sTitle.get(normalizeTitle(title));return {ajg:c?(Number(c.ajg_2024)===5?'4*':String(c.ajg_2024??'Not listed')):'Not listed',sjr:s?.sjr==null?'Not listed':String(s.sjr),sjrQuartile:s?.quartile??'',rankingMatch:ct||st?'ISSN':c||s?'Journal title':'No exact match'};};}
